      int nOutPos;
      nMagnitude = (nDigitCount - 1) / 3 - 1;
      if (nMagnitude < 4) {
        if (nMagnitude < 0) {
          nMagnitude = 0;
        }
      } else {
        nMagnitude = 4;
      }

      nDigitCount += nMagnitude * -3;
      nOutPos = (nDigitCount - 1) / 3 + nDigitCount;
      if (nOutPos < 1 || nOutPos >= nParam - 2) {
        goto write_placeholder;
      }

      wszText[nOutPos + 1] = L'\0';
